<script lang="ts">
 import type {Project} from '../model';
 import {MONTHS_FA} from '../model';
 import {design,energy,num}from '../engine/calculate';
 import BarChart from './BarChart.svelte';
 export let project:Project;export let update:(p:Partial<Project>)=>void;
 $: d=design(project);$: e=energy(project,d);
 const n=(event:Event)=>Number((event.currentTarget as HTMLInputElement).value);
</script>
<section class="stage-heading"><h1>محاسبات تولید نیروگاه</h1><p>نتایج با تغییر آرایش پنل، شرایط تابش و ضرایب تلفات دوباره محاسبه می‌شوند.</p></section>
<div class="kpi-row"><div class="kpi"><span>ظرفیت DC</span><b class="Fa-Num">{num(d.dcKw,2)} <small>kWp</small></b></div><div class="kpi"><span>ظرفیت AC</span><b class="Fa-Num">{num(d.acKw,2)} <small>kW</small></b></div><div class="kpi"><span>تولید سالانه</span><b class="Fa-Num">{num(e.annual)} <small>kWh</small></b></div><div class="kpi"><span>تولید ویژه</span><b class="Fa-Num">{num(e.specific)} <small>kWh/kWp</small></b></div><div class="kpi"><span>ضریب ظرفیت AC</span><b class="Fa-Num">{num(e.capacityFactor,1)}%</b></div></div>
{#if d.errors.length}<div class="message message-error">به‌دلیل ناسازگاری طراحی، برآورد تولید صفر نمایش داده می‌شود. ابتدا خطاهای مرحله تجهیزات را اصلاح کنید.</div>{/if}
<div class="production-layout"><div class="panel"><div class="panel-head"><h2>تولید ماهانه نیروگاه</h2><span class="chip">kWh | فروردین تا اسفند، چپ به راست</span></div><BarChart values={e.monthly} labels={MONTHS_FA}/><div class="hint">مدل اولیه بر پایه PSH روزانه × روزهای ماه × ظرفیت DC × نسبت عملکرد و جهت است. اثر clipping، سایه زمانی و شبیه‌سازی ساعتی محاسبه نشده است.</div></div>
<div class="panel"><div class="panel-head"><h2>فرضیات تولید</h2></div><div class="form-grid"><label>تلفات غیراینورتر (%)<input type="number" min="0" max="80" step="0.5" value={project.climate.lossesPct} oninput={e=>update({climate:{...project.climate,lossesPct:n(e)}})}/></label><label>ضریب جهت و شیب<input type="number" min="0" max="1.5" step="0.01" value={project.climate.orientationFactor} oninput={e=>update({climate:{...project.climate,orientationFactor:n(e)}})}/></label></div><div class="hint">مقادیر PSH پیش‌فرض فقط نمونه آموزشی‌اند و به محل واقعی متصل نیستند. لطفاً داده اندازه‌گیری‌شده یا منبع معتبر را ثبت کنید.</div><div class="psh-grid">{#each MONTHS_FA as month,i}<label>{month}<input type="number" min="0" step="0.1" value={project.climate.psh[i]} oninput={ev=>update({climate:{...project.climate,psh:project.climate.psh.map((v,j)=>i===j?n(ev):v),verified:false}})}/></label>{/each}</div><label class="checkbox-row"><input type="checkbox" checked={project.climate.verified} onchange={e=>update({climate:{...project.climate,verified:e.currentTarget.checked}})}/> منبع داده PSH را به‌صورت مستقل بررسی و تأیید کرده‌ام.</label></div></div>
<div class="layout-two lower-cards"><div class="panel"><h2>جدول تولید ماهانه</h2><div class="table-scroll"><table><thead><tr><th>ماه</th><th>PSH (h/day)</th><th>تولید (kWh)</th><th>سهم سالانه</th></tr></thead><tbody>{#each MONTHS_FA as m,i}<tr><td>{m}</td><td>{num(project.climate.psh[i],2)}</td><td>{num(e.monthly[i])}</td><td>{num(e.annual>0?e.monthly[i]/e.annual*100:0,1)}%</td></tr>{/each}</tbody></table></div></div><div class="panel"><h2>تفکیک محدودیت‌ها و فرضیات</h2><div class="message message-warning">مقادیر مدل آب‌وهوایی تا هنگام ثبت منبع معتبر، برآورد مقدماتی محسوب می‌شوند.</div><div class="spec-grid large"><span>افت کلی مدل <b>{num(project.climate.lossesPct,1)}%</b></span><span>ضریب جهت <b>{num(project.climate.orientationFactor,2)}</b></span><span>میانگین PSH <b>{num(project.climate.psh.reduce((a,b)=>a+b,0)/12,2)} h</b></span><span>تعداد ماژول <b>{num(d.installedPanels)}</b></span></div>{#each d.warnings as warning}<div class="message message-warning">{warning}</div>{/each}</div></div>

